def reduction_operations_to_equal(nums):
    ordered = sorted(nums)
    levels_below = 0
    operations = 0
    for index in range(1, len(ordered)):
        if ordered[index] != ordered[index - 1]:
            levels_below += 1
        operations += levels_below
    return operations

